window.CHALLENGES_I18N = window.CHALLENGES_I18N || {};
window.CHALLENGES_I18N["en"] = {"expr-001":{"meaning":"To be hungover.","example":"Last night I drank too much, and this morning I'm really hungover.","secondExample":"After the party, the students were hungover and regretted their excesses.","literal":"to have a wooden mouth","options":["To be exhausted after a long day at work.","To have a headache after drinking too much.","To be in a bad mood for no real reason.","To be shocked by some unexpected news."],"microActivity":"Last night I drank too much at the party, so this morning I'm hungover and I don't want to go out.","profNote":"It's casual and takes {avoir}: {j'ai la gueule de bois}. For a person's face, {gueule} is rude."},"expr-002":{"meaning":"To bother or really irritate someone; to get on someone's nerves.","example":"Stop making that noise, you've been driving me nuts since this morning!","secondExample":"I tried to explain the situation to him calmly, but he kept asking me the same questions, and it was driving me nuts.","literal":"to break (someone's) feet","options":["To make a loud noise","To be really tired","To annoy someone a lot","To break something"],"microActivity":"My brother forgot to do the dishes again, he's getting on my nerves!","profNote":"The annoyed person goes before the verb: {tu me casses les pieds}. Casual, but no swear word."},"expr-003":{"meaning":"To stand someone up; to not show up to an appointment.","example":"I was really mad because my friend stood me up last night.","secondExample":"She decided to stand him up because she didn't want to see him anymore.","literal":"to put a rabbit","options":["To play a prank on a friend.","To not show up without warning.","To invite someone over to eat.","To tell someone a funny joke."],"microActivity":"You shouldn't stand someone up when you've promised to come.","profNote":"The person stood up goes before the verb: {il m'a posé un lapin}. Casual, for a date or any plan."},"lt-auto-001":{"referenceTranslations":["I bought a new book yesterday and I've already finished it.","I bought a new book yesterday and I already finished it.","Yesterday I bought a new book and I've already finished it."]},"lt-auto-002":{"referenceTranslations":["This weekend, we're going to visit a museum downtown.","This weekend we are going to visit a museum in the city center.","We're going to visit a museum downtown this weekend."]},"lt-auto-003":{"referenceTranslations":["She's a little tired because she worked a lot today.","She is a bit tired because she worked a lot today.","Because she worked so much today, she's a little tired."]},"accent-auto-001":{"explanation":"\"e\" has an acute accent."},"accent-auto-002":{"explanation":"\"e\" has a circumflex accent."},"accent-auto-003":{"explanation":"\"a\" has a grave accent."},"accent-auto-004":{"explanation":"\"e\" has an acute accent, \"a\" has a grave accent."},"accent-auto-005":{"explanation":"\"e\" has a grave accent."},"accent-auto-006":{"explanation":"\"c\" has a cedilla."},"lt-a1m1-001":{"referenceTranslations":["Good evening, how are you?","Good evening, how's it going?","Good evening, how are you doing?"],"explanation":"\"Bonsoir\" is the evening greeting; \"ça va ?\" is the informal question \"how are you?\"."},"lt-a1m1-002":{"referenceTranslations":["A coffee, please.","One coffee, please.","A coffee, if you please."],"explanation":"\"S'il vous plaît\" is the polite \"please\"; \"un café\" asks for the item without a verb."},"lt-a1m1-003":{"referenceTranslations":["What's your name?","What is your name?","What do you call yourself?"],"explanation":"In French you say \"comment tu t'appelles\" (literally \"how do you call yourself\"); in English the natural way is \"what's your name?\"."},"lt-a1m1-004":{"referenceTranslations":["I am Brazilian.","I'm Brazilian.","I'm a Brazilian woman."],"explanation":"\"Brésilienne\" is the feminine form of \"brésilien\"."},"lt-a1m1-005":{"referenceTranslations":["I am twenty years old.","I'm twenty years old.","I'm 20 years old.","I am 20."],"explanation":"To give your age, French uses \"avoir\" (to have), not \"être\" (to be) as English does."},"lt-a1m1-006":{"referenceTranslations":["How old are you?","What is your age?","What's your age?"],"explanation":"In the inversion \"as-tu\", the verb comes before the subject: \"quel âge as-tu ?\" = \"how old are you?\" (literally \"what age have you?\")."},"lt-a1m1-007":{"referenceTranslations":["My father's name is Marc.","My dad's name is Marc.","My father is called Marc."],"explanation":"\"Mon\" is the masculine possessive (\"my\"); \"s'appelle\" means \"is called\" (a reflexive verb, literally \"calls himself\")."},"lt-a1m1-008":{"referenceTranslations":["I have a brother and a sister.","I've got a brother and a sister."],"explanation":"\"Un\" is masculine (frère) and \"une\" is feminine (sœur): the article agrees with the gender of the noun."},"accent-a1m1-001":{"explanation":"The \"i\" in \"plaît\" has a circumflex accent."},"accent-a1m1-002":{"explanation":"\"e\" has an acute accent."},"accent-a1m1-003":{"explanation":"\"e\" has an acute accent."},"accent-a1m1-004":{"explanation":"The first \"e\" has a circumflex accent."},"accent-a1m1-005":{"explanation":"\"e\" has an acute accent."},"accent-a1m1-006":{"explanation":"\"a\" has a circumflex accent."},"accent-a1m1-007":{"explanation":"\"e\" has a grave accent."},"accent-a1m1-008":{"explanation":"\"e\" has a grave accent."},"accent-a1m1-009":{"explanation":"\"e\" has a grave accent."},"expr-a1m1-001":{"meaning":"Nice to meet you. (Women say \"enchantée\"; it sounds the same.)","example":"— Hello, my name is Léo.\n— Nice to meet you!","secondExample":"I'm Ana. Nice to meet you!","options":["When you meet someone","When you say goodbye","When you're hungry","When you're tired"],"microActivity":"Hi, my name is Ana. — Nice to meet you!","profNote":"Men write {enchanté}, women write {enchantée}, and they sound the same."},"expr-a1m1-002":{"meaning":"So-so; not great, not bad.","example":"— How's it going?\n— So-so.","secondExample":"My French? So-so.","literal":"like this, like that","options":["So-so, neither good nor bad","Very good","Very bad","Right away"],"microActivity":"How are you? — So-so."},"expr-a1m1-003":{"meaning":"Not bad; pretty good.","example":"— How's it going?\n— Not bad, thanks!","secondExample":"This coffee isn't bad.","options":["Pretty good","Very bad","Very expensive","Very late"],"microActivity":"How are you? — Not bad, thanks!","profNote":"A common answer to {ça va ?}. Like \"not bad\" in English, it means \"pretty good\"."},"expr-a1m1-004":{"meaning":"Deal! Sounds good! Great!","example":"— Coffee together?\n— Sounds good!","secondExample":"— I'll call you tonight.\n— Works for me!","literal":"That works!","options":["OK, sounds good","I don't understand","I'm hungry","Goodbye"],"microActivity":"A coffee? — Sounds good!","profNote":"It's casual but everywhere: friends, coworkers, even waiters. In formal settings, pick something else."},"expr-a1m1-005":{"meaning":"No problem! No worries!","example":"— Sorry!\n— No problem!","secondExample":"— Can you help me?\n— No problem.","options":["It's no big deal","It's very difficult","I'm tired","I don't know"],"microActivity":"Sorry! — No problem!","profNote":"Use it to answer a {pardon !} or a request for help, with anyone."},"lt-a1m2-001":{"referenceTranslations":["I would like some cheese, please.","I'd like some cheese, please.","I would like cheese, please."],"explanation":"\"Je voudrais\" (\"I would like\") is the polite way to ask for something; \"du\" (de + le) means an amount of cheese, \"some cheese\"."},"lt-a1m2-002":{"referenceTranslations":["Do you drink milk in the morning?","Do you have milk in the morning?","Do you drink milk every morning?"],"explanation":"\"Du lait\" uses the partitive article: milk isn't something you count, so it's \"du\", not \"un\"."},"lt-a1m2-003":{"referenceTranslations":["I get up at six o'clock.","I get up at six.","I wake up at six o'clock."],"explanation":"Reflexive verb: \"je me lève\" is literally \"I get myself up\"; the time comes with \"à ... heures\"."},"lt-a1m2-004":{"referenceTranslations":["It's seven o'clock in the evening.","It is seven in the evening.","It's seven p.m.","It's 7 p.m."],"explanation":"To tell the time, French says \"il est sept heures\" (literally \"it is seven hours\"); \"du soir\" means \"in the evening\"."},"lt-a1m2-005":{"referenceTranslations":["Today is Tuesday.","Today it's Tuesday.","It's Tuesday today."],"explanation":"For the day of the week, French says \"nous sommes mardi\" (literally \"we are Tuesday\"); in English you say \"today is Tuesday\"."},"lt-a1m2-006":{"referenceTranslations":["I work tomorrow morning.","I'm working tomorrow morning.","I am working tomorrow morning."],"explanation":"\"Demain matin\" means \"tomorrow morning\"; the present tense \"je travaille\" can also talk about the near future, like \"I'm working tomorrow\" in English."},"accent-a1m2-001":{"explanation":"\"e\" has an acute accent."},"accent-a1m2-002":{"explanation":"\"e\" has an acute accent."},"accent-a1m2-003":{"explanation":"Both \"e\"s have an acute accent."},"accent-a1m2-004":{"explanation":"\"o\" has a circumflex accent."},"accent-a1m2-005":{"explanation":"\"e\" has an acute accent."},"accent-a1m2-006":{"explanation":"\"e\" has an acute accent."},"accent-a1m2-007":{"explanation":"\"o\" has a circumflex accent."},"accent-a1m2-008":{"explanation":"\"à\" has a grave accent."},"expr-a1m2-001":{"meaning":"Enjoy your meal!","example":"— Here's your dish.\n— Enjoy your meal!","secondExample":"Enjoy your meal, everyone!","options":["Before eating","When waking up","When leaving the house","When you're sick"],"microActivity":"Dinner is ready. — Enjoy your meal!","profNote":"Said at the table, right before eating. To answer: {merci, vous aussi !} or {toi aussi !}"},"expr-a1m2-002":{"meaning":"Time to eat! Come to the table!","example":"Kids, come to the table!","secondExample":"Come to the table! Dinner is ready.","literal":"To the table!","options":["Come and eat","Go to sleep","Go to work","Clear the table"],"microActivity":"Mom calls out: \"Dinner's ready!\"","profNote":"It's the call that the meal is ready, very much a family thing: {les enfants, à table !}"},"expr-a1m2-003":{"meaning":"See you in a bit!","example":"— I'm going to the market.\n— See you later!","secondExample":"I'm leaving at noon. See you later!","options":["When you'll see each other again soon","When you'll never see each other again","When you'll see each other next week","When you arrive"],"microActivity":"I'm off to work. — See you later!","profNote":"Only for someone you'll see again the same day. For another day, say {à demain} or {à bientôt}."},"expr-a1m2-004":{"meaning":"Right now; right away.","example":"— Are you coming?\n— Yes, right away!","secondExample":"I'm coming right away.","options":["Immediately","Much later","Never","In the evening"],"microActivity":"Are you coming to eat? — Yes, right away!","profNote":"The go-to reply when someone calls you: {oui, tout de suite !} Don't mix it up with {tout à l'heure}."},"expr-a1m2-005":{"meaning":"Have a good day!","example":"Goodbye, and have a good day!","secondExample":"Thanks, have a good day!","options":["When leaving during the day","When going to bed at night","Before starting a meal","When arriving somewhere"],"microActivity":"Bye, have a nice day!","profNote":"A daytime goodbye you can say to anyone, even the cashier. In the evening, switch to {bonne soirée}."},"lt-a1m3-001":{"referenceTranslations":["The museum is far from here.","The museum is far away from here.","The museum is a long way from here."],"explanation":"\"Loin de\" = \"far from\", and \"d'ici\" = de + ici (\"from here\"). To say where a place is, French uses \"être\": \"est loin\" = \"is far\"."},"lt-a1m3-002":{"referenceTranslations":["Turn right, then go straight.","Turn right and then go straight ahead.","Turn right, then straight ahead."],"explanation":"\"Tournez\" is the polite imperative (vous); \"tout droit\" = \"straight ahead\"."},"lt-a1m3-003":{"referenceTranslations":["I come from Brazil, and you?","I'm from Brazil, and you?","I am from Brazil, and you?"],"explanation":"\"Je viens de\" tells where you're from: \"du\" = de + le (du Brésil); \"et toi ?\" turns the question back around."},"lt-a1m3-004":{"referenceTranslations":["She is American.","She's American."],"explanation":"Nationality agrees with the person: \"américain\" (he), \"américaine\" (she), and in the feminine the \"n\" is pronounced. As an adjective, it's written in lowercase."},"lt-a1m3-005":{"referenceTranslations":["The pants cost fifty euros.","The pants are fifty euros.","The trousers cost fifty euros."],"explanation":"\"Coûte\" is the form of the verb \"coûter\" (to cost) for a single thing: in French, \"le pantalon\" is singular; \"cinquante\" = 50."},"lt-a1m3-006":{"referenceTranslations":["I'm looking for a dress.","I am looking for a dress."],"explanation":"\"Je cherche\" already means \"I'm looking for\": French uses the simple present for an action in progress."},"lt-a1m3-007":{"referenceTranslations":["I buy vegetables and rice.","I'm buying vegetables and rice.","I am buying vegetables and rice."],"explanation":"\"Des\" is the plural indefinite article (vegetables) and \"du\" is the partitive (rice, which you don't count)."},"lt-a1m3-008":{"referenceTranslations":["Do you want sugar?","Do you want some sugar?","Would you like sugar?"],"explanation":"\"Du\" is the partitive: some of something you don't count (sugar); English says \"some sugar\" or just \"sugar\". \"Tu veux\" is the informal \"you want\", and the question comes from intonation alone."},"lt-a1m3-009":{"referenceTranslations":["I'll take a kilo of apples.","I take a kilo of apples.","I'll take one kilo of apples."],"explanation":"After a quantity, French uses \"de\" with no article: \"un kilo de pommes\"."},"lt-a1m3-010":{"referenceTranslations":["A bottle of water, please.","One bottle of water, please."],"explanation":"After a container comes \"de\" with no article, and \"de\" becomes \"d'\" before a vowel: \"une bouteille d'eau\"."},"accent-a1m3-001":{"explanation":"\"e\" has a grave accent."},"accent-a1m3-002":{"explanation":"\"o\" has a circumflex accent."},"accent-a1m3-003":{"explanation":"\"e\" has an acute accent."},"accent-a1m3-004":{"explanation":"\"u\" has a grave accent: \"où\" = where; \"ou\" (no accent) = or."},"accent-a1m3-005":{"explanation":"\"u\" has a circumflex accent."},"accent-a1m3-006":{"explanation":"\"e\" has an acute accent."},"accent-a1m3-007":{"explanation":"\"a\" has a circumflex accent."},"accent-a1m3-008":{"explanation":"\"e\" has a grave accent."},"expr-a1m3-001":{"meaning":"Excuse me! Sorry!","example":"Excuse me, where is the train station?","secondExample":"Sorry, I'm late.","options":["To get someone's attention","To say goodbye to someone","To thank someone for their help","To turn down someone's request"],"microActivity":"Excuse me, where is the museum?","profNote":"It uses {vous}, so it's the polite way to stop a stranger. With friends, say {excuse-moi}."},"expr-a1m3-002":{"meaning":"You're welcome; please, go ahead.","example":"— Thank you so much!\n— You're welcome.","secondExample":"Please, come in.","literal":"I beg you","options":["You're welcome","Goodbye","I don't know","Sorry"],"microActivity":"Thank you! — You're welcome.","profNote":"A politer {de rien}, with {vous}. With friends: {je t'en prie}. It can also mean \"go ahead\" or \"after you\"."},"expr-a1m3-003":{"meaning":"How much is it? How much does that come to?","example":"How much is it, please?","secondExample":"How much is it for both?","literal":"That makes how much?","options":["What's the price?","What time is it?","Where is it?","Who is it?"],"microActivity":"How much is it, please?","profNote":"For the total at the checkout. To ask the price of just one thing, say {c'est combien ?}"},"expr-a1m3-004":{"meaning":"It's too expensive!","example":"A hundred euros? That's too expensive!","secondExample":"This bag is pretty, but it's too expensive.","options":["The price is too high","The price is perfect","It's free","It's very small"],"microActivity":"Eighty euros? That's too expensive!","profNote":"Watch the {trop}: it means \"too much\". If it's just \"very expensive\", say {c'est très cher}."},"expr-a1m3-005":{"meaning":"Anything else?","example":"— A kilo of apples.\n— Anything else?","secondExample":"— Anything else?\n— A bottle of water.","literal":"And with that?","options":["The salesperson","The customer","The doctor","The teacher"],"microActivity":"A liter of milk. — Anything else?","profNote":"What the seller asks at the market or bakery. If you're done, answer {c'est tout, merci}."},"lt-a1m4-001":{"referenceTranslations":["It's cold in winter.","It is cold in the winter.","It gets cold in winter."],"explanation":"Weather uses \"il fait\" (il fait froid), where English says \"it's cold\"."},"lt-a1m4-002":{"referenceTranslations":["Today it's raining.","It's raining today.","Today it is raining."],"explanation":"\"Il pleut\" is impersonal: the \"il\" isn't a person, just like the \"it\" in \"it's raining\"."},"lt-a1m4-003":{"referenceTranslations":["I take the bus every day.","I take the bus daily.","Every day I take the bus."],"explanation":"\"Prendre le bus\" means \"to take the bus\"; \"tous les jours\" = \"every day\"."},"lt-a1m4-004":{"referenceTranslations":["Where is the metro station?","Where's the subway station?","Where is the subway station?"],"explanation":"\"Où est\" asks where something is; \"station de métro\" = \"metro (subway) station\"."},"lt-a1m4-005":{"referenceTranslations":["He has a stomachache.","His stomach hurts.","He has a bellyache."],"explanation":"Pain is expressed with \"avoir mal à\": \"il a mal au ventre\" (à + le = au) = \"he has a stomachache\"."},"lt-a1m4-006":{"referenceTranslations":["I'm going to the pharmacy.","I am going to the pharmacy.","I go to the pharmacy."],"explanation":"\"Aller à la\" shows the destination; \"pharmacie\" is feminine, so it's \"à la\"."},"accent-a1m4-001":{"explanation":"Both \"é\"s have an acute accent."},"accent-a1m4-002":{"explanation":"\"e\" has an acute accent."},"accent-a1m4-003":{"explanation":"\"e\" has an acute accent."},"accent-a1m4-004":{"explanation":"\"e\" has a circumflex accent."},"accent-a1m4-005":{"explanation":"\"à\" has a grave accent."},"accent-a1m4-006":{"explanation":"\"e\" has a circumflex accent."},"accent-a1m4-007":{"explanation":"\"e\" has an acute accent."},"accent-a1m4-008":{"explanation":"\"e\" has a grave accent."},"expr-a1m4-001":{"meaning":"It's raining cats and dogs; it's pouring.","example":"Take an umbrella, it's pouring!","secondExample":"It's been pouring since this morning.","literal":"it's raining ropes","options":["It's raining very hard","It's not raining","It's snowing","The weather is nice"],"microActivity":"It's raining cats and dogs outside!"},"expr-a1m4-002":{"meaning":"Have a good trip!","example":"Are you leaving tomorrow? Have a good trip!","secondExample":"Have a good trip and see you soon!","options":["To someone who is leaving","To someone who is arriving","To someone who is eating","To someone who is sleeping"],"microActivity":"Goodbye, have a good trip!","profNote":"For anyone leaving on a trip. Before a holiday, French also says {bonnes vacances !}"},"expr-a1m4-003":{"meaning":"Get well soon!","example":"Are you sick? Get well soon!","secondExample":"Get well, see you soon!","options":["To a sick person","To a person on vacation","To a person who is leaving","To a person who is eating"],"microActivity":"He has a fever. — Get well soon!","profNote":"For anyone sick or recovering. With friends, you can also say {soigne-toi bien !}"},"expr-a1m4-004":{"meaning":"Bless you! (when someone sneezes)","example":"— Achoo!\n— Bless you!","secondExample":"Bless you, ma'am!","literal":"To your wishes!","options":["When someone sneezes","When someone eats","When someone leaves","When someone arrives"],"microActivity":"Achoo! — Bless you!","profNote":"This one uses {tu}, for friends and family. With people you don't know, say {à vos souhaits !}"},"expr-a1m4-005":{"meaning":"What weather! (commenting on the weather)","example":"Ugh, this weather! It's raining again.","secondExample":"Ugh, this weather! It's freezing.","options":["You comment on the weather","You ask what time it is","You say goodbye to someone","You thank someone for a favor"],"microActivity":"What weather! It's snowing!","profNote":"{Quel temps !} is an exclamation, not a question. It's usually a complaint, but tone can flip it."},"lt-a1m5-001":{"referenceTranslations":["My sister is tall and kind.","My sister is tall and nice.","My sister is tall and friendly."],"explanation":"The adjectives agree with \"sœur\" (feminine): \"grande\", \"gentille\" (masculine: gentil)."},"lt-a1m5-002":{"referenceTranslations":["His sweater is red.","Her sweater is red.","Her pullover is red."],"explanation":"\"Son\" can mean \"his\" or \"her\": it agrees with \"pull\" (masculine), not with the owner."},"lt-a1m5-003":{"referenceTranslations":["The kitchen is next to the living room.","The kitchen is beside the living room.","The kitchen is adjacent to the living room."],"explanation":"\"À côté de\" = \"next to\"; \"de + le\" becomes \"du\" (du salon)."},"lt-a1m5-004":{"referenceTranslations":["There is a window in the bedroom.","There's a window in the bedroom.","There is a window in the room."],"explanation":"\"Il y a\" = \"there is / there are\"; \"dans\" shows where something is."},"lt-a1m5-005":{"referenceTranslations":["The lamp is on the table.","The lamp is on top of the table.","The lamp is sitting on the table."],"explanation":"\"Lampe\" is a lamp (a floor lamp or a table lamp); \"sur\" means on top of something."},"lt-a1m5-006":{"referenceTranslations":["The bag is under the chair.","The bag is underneath the chair.","The bag is below the chair."],"explanation":"\"Sous\" means \"under\"; the opposite is \"sur\" (on)."},"accent-a1m5-001":{"explanation":"\"e\" has a grave accent."},"accent-a1m5-002":{"explanation":"\"e\" has a circumflex accent."},"accent-a1m5-003":{"explanation":"\"e\" has an acute accent."},"accent-a1m5-004":{"explanation":"\"e\" has a grave accent."},"accent-a1m5-005":{"explanation":"\"e\" has an acute accent."},"accent-a1m5-006":{"explanation":"\"à\" has a grave accent, \"ô\" has a circumflex accent, and \"é\" has an acute accent."},"expr-a1m5-001":{"meaning":"Make yourself at home.","example":"Come in, make yourself at home!","secondExample":"This is the living room. Make yourself at home.","literal":"Do as at your place","options":["To a guest who's arriving","To a neighbor who's leaving","To a friend who's sick","To a customer in a store"],"microActivity":"Come in! Make yourself at home!","profNote":"This is the {tu} version, for people you're close to. For a more formal guest: {faites comme chez vous}."},"expr-a1m5-002":{"meaning":"At my place; at home.","example":"Come over to my place tonight!","secondExample":"My place has two bedrooms.","literal":"at the home of me","options":["At my house","At your school","At the restaurant","At the station"],"microActivity":"Tonight we're eating at my place.","profNote":"{Chez} already means \"at the home of\": {chez moi}, {chez toi}, {chez Marie}. No need for {maison}."},"expr-a1m5-003":{"meaning":"Welcome!","example":"Welcome to my place!","secondExample":"Welcome to Paris!","options":["When you welcome someone","When you're about to leave","When you sit down to eat","When you're going to bed"],"microActivity":"Welcome to my home!","profNote":"On its own, {bienvenue !} stays the same for anyone. To welcome someone home: {bienvenue chez moi}."},"expr-a1m5-004":{"meaning":"It looks good on you! It suits you!","example":"That red dress looks good on you!","secondExample":"Blue suits you.","literal":"That goes well on you!","options":["It looks nice on you","It's too small","It's too expensive","It's dirty"],"microActivity":"That green sweater looks good on you!","profNote":"To compliment clothes, a color or a haircut, with {tu}. With someone you call {vous}: {ça vous va bien}."},"expr-a1m5-005":{"meaning":"Do you like it? Do you like that?","example":"My new house, do you like it?","secondExample":"Do you like this color?","literal":"Does it please you?","options":["Do you like it?","Are you hungry?","Are you tired?","Are you coming?"],"microActivity":"Do you like this dress?","profNote":"Careful: the thing does the pleasing, not you. To say you like it, answer {oui, ça me plaît !}"},"lt-a1m6-001":{"referenceTranslations":["On weekends, I like to read.","On the weekend, I like to read.","I like to read on weekends."],"explanation":"\"Le week-end\" with no preposition shows a habit (\"on weekends\"); \"j'aime lire\" = \"I like to read\" (infinitive)."},"lt-a1m6-002":{"referenceTranslations":["Are we going to the movies on Saturday night?","Shall we go to the movies Saturday night?","Are we going to the cinema on Saturday night?"],"explanation":"In spoken French, \"on\" means \"we\"; \"au cinéma\" = à + le cinéma."},"lt-a1m6-003":{"referenceTranslations":["Yesterday I ate at the restaurant.","Yesterday I ate at a restaurant.","I ate at the restaurant yesterday."],"explanation":"\"Hier\" (\"yesterday\") calls for the passé composé: \"j'ai mangé\" (avoir + past participle)."},"lt-a1m6-004":{"referenceTranslations":["This morning I took the bus.","This morning, I took the bus.","I took the bus this morning."],"explanation":"\"Ce matin\" (\"this morning\") is part of today; \"j'ai pris\" is the passé composé of \"prendre\"."},"accent-a1m6-001":{"explanation":"\"e\" has an acute accent."},"accent-a1m6-002":{"explanation":"\"e\" has an acute accent."},"accent-a1m6-003":{"explanation":"\"e\" has a grave accent."},"accent-a1m6-004":{"explanation":"\"e\" has an acute accent."},"accent-a1m6-005":{"explanation":"\"e\" has an acute accent."},"expr-a1m6-001":{"meaning":"Have a good weekend!","example":"Goodbye, have a good weekend!","secondExample":"Thanks, you have a good weekend too!","options":["Before the weekend","On Monday morning","On Christmas Eve","At a birthday"],"microActivity":"See you Monday! Have a good weekend!","profNote":"The Friday goodbye at work or school. Note the French spelling: {week-end}, with a hyphen."},"expr-a1m6-002":{"meaning":"Have a good evening!","example":"Goodbye, have a good evening!","secondExample":"Thank you, have a good evening too!","options":["In the evening, when leaving","In the morning, when arriving","At noon, before eating","At midnight, when waking up"],"microActivity":"Goodbye, have a nice evening!","profNote":"It's for goodbyes; when you arrive, it's {bonsoir}. At bedtime, it's {bonne nuit}."},"expr-a1m6-003":{"meaning":"Let's go! Here we go!","example":"The movie is starting. Here we go!","secondExample":"Do we have everything? Then here we go!","literal":"It has set off!","options":["Let's start","Let's stop","Let's go home","Let's go to sleep"],"microActivity":"3, 2, 1... Here we go!","profNote":"{C'est parti !} kicks things off with energy: a game, a trip, a lesson. Fine with anyone."},"expr-a1m6-004":{"meaning":"What's new? What's up, any news?","example":"Hi! What's new?","secondExample":"What's new since last week?","literal":"What of new?","options":["Any news?","What time is it?","Where are you from?","How old are you?"],"microActivity":"Hi! What's new?","profNote":"Casual, for friends, right after {salut}. Nothing to report? Just say {rien de spécial}."},"expr-a1m6-005":{"meaning":"Long time no see! It's been a while!","example":"Hi Marc! It's been a long time!","secondExample":"I haven't seen you in a long time!","literal":"That makes a long time!","options":["We haven't seen each other in ages","We'll see each other again tomorrow","We're running really late","We're absolutely starving"],"microActivity":"Hi! Long time no see!","profNote":"What you say when you run into someone after ages. To give the length: {ça fait deux ans}."},"expr-lote1-001":{"meaning":"anything / nonsense","example":"— The Earth is flat.\n— You're talking nonsense!","secondExample":"He ate a bunch of junk for dinner, and now he has a stomachache.","literal":"any thing","options":["Something silly or meaningless","Something very important","Something very expensive","Something very fast"],"microActivity":"Stop going on about your cat that speaks English, you're talking nonsense!","profNote":"Meaning \"anything\", it's neutral. Meaning \"nonsense\", it's blunt: {tu dis n'importe quoi !} is for friends."},"expr-lote1-002":{"meaning":"to be fed up","example":"I'm sick of the rain, I want sunshine!","secondExample":"The kids were fed up with waiting in the car.","options":["To be very hungry","To be sick of a situation","To be very happy","To have a lot of money"],"microActivity":"I've been doing my homework for three hours, I'm fed up!","profNote":"Don't drop the {en}: {j'en ai marre}. Add what with {de}: {j'en ai marre du bruit}. It's casual."},"expr-lote1-003":{"meaning":"to not give a damn","example":"— Your team lost!\n— I don't give a damn, I don't like soccer.","secondExample":"She couldn't care less what people say.","options":["To be totally indifferent to something","To be very proud of oneself","To be very angry with someone","To be very scared of something"],"microActivity":"He can criticize my haircut, I don't fucking care: I like it.","profNote":"Very common among friends, but crude: never with your boss or strangers. Neutral: {ça m'est égal}."},"expr-lote1-004":{"meaning":"to be in deep trouble / in a terrible situation","example":"I missed my train and I have an interview in twenty minutes: I'm in deep shit.","secondExample":"Without their keys or their phone, they were in deep shit.","options":["To work in a garden","To be in a very good mood","To have a very big problem","To be very comfortably settled"],"microActivity":"My computer broke down the day before I had to hand in my thesis: I'm in deep shit!","profNote":"Vulgar: only with people you're very close to, ideally about yourself: {je suis dans la merde}."},"expr-lote1-005":{"meaning":"that sucks / what a mess","example":"The concert is canceled? That sucks, I already had my tickets.","secondExample":"That neighborhood at night was a bit sketchy, so we took a taxi.","options":["It's delicious","It's perfectly normal","It's lame or worrying","It's very easy"],"microActivity":"The battery's dead and we're lost in the forest… this sucks!","profNote":"Very common in everyday speech. It can also mean a place is sketchy: {ce quartier craint}."},"expr-lote1-006":{"meaning":"to feel lazy / can't be bothered","example":"I can't be bothered to cook tonight, want to order a pizza?","secondExample":"On Sunday, he felt too lazy to go out, so he stayed in bed.","literal":"to have the phlegm","options":["To feel like working out","To have a fever","To be in a big hurry","To not feel like making an effort"],"microActivity":"The laundry is dry, but I can't be bothered to fold it right now.","profNote":"It takes {de} + verb: {j'ai la flemme de cuisiner}. Very casual, so not something to tell your boss."},"expr-lote1-007":{"meaning":"that's crazy / that's incredible","example":"He ran the marathon in under three hours? That's crazy!","secondExample":"It was crazy: it was snowing in the middle of May.","options":["It's very boring","It's incredible or surprising","It's very logical","It's a little sad"],"microActivity":"She speaks six languages and she's only fifteen, that's crazy!","profNote":"Works for good or bad surprises, just like {c'est fou}. Casual, for friends."},"expr-lote1-008":{"meaning":"to get out / to get the hell out","example":"The neighbor yelled: \"Get the hell out of my garden!\"","secondExample":"By the time the police arrived, the thieves had already taken off.","literal":"to break camp (with a vulgar verb)","options":["To pitch a tent","To party","To get to work","To leave quickly, to go away"],"microActivity":"He'd had enough of that job and decided to get the hell out and move abroad.","profNote":"As an order it's aggressive: {foutez le camp !} {Je fous le camp} just means \"I'm leaving\", but crudely."},"expr-lote1-009":{"meaning":"shut up","example":"— You lost again, huh?\n— Oh, shut your trap!","secondExample":"Annoyed by his brother's jokes, Paul snapped: \"Shut the hell up, seriously!\"","literal":"your muzzle","options":["To congratulate someone","To ask someone the time","To say hi to a friend","To tell someone to shut up"],"microActivity":"Stop singing off-key at two in the morning, shut the hell up!","profNote":"It truly offends; only among close friends, joking. Not crude, but still curt: {tais-toi}."},"expr-lote1-010":{"meaning":"to be a pain in the neck / to piss someone off","example":"It pisses me off to have to work this Saturday.","secondExample":"Your dog barked all night again, he really pissed us off.","literal":"to make (someone) shit","options":["To help someone sleep","To annoy or bother a lot","To make someone rich","To please a lot"],"microActivity":"Stop asking me the same question every five minutes, you're pissing me off!","profNote":"It's vulgar: you'll mostly hear {ça me fait chier}. Avoid it with anyone you don't know well."},"expr-lote1-011":{"meaning":"to stress out / to argue over nothing","example":"Don't stress about it, we'll pick the restaurant when we get there.","secondExample":"Yesterday, my parents got into a pointless argument over the remote control.","literal":"to take one's head","options":["To overcomplicate things","To rest for a long time","To wash your hair slowly","To compliment yourself"],"microActivity":"You've been arguing over nothing for two hours: stop getting so worked up!","profNote":"Very common as advice to calm someone down: {ne te prends pas la tête}. Casual."},"expr-lote1-012":{"meaning":"yeah right! / no way!","example":"— He's going to clean his room by himself.\n— Yeah, right! He's never done it.","secondExample":"— The bus will be on time today.\n— Yeah, right, it's already twenty minutes late!","literal":"you speak!","options":["I totally agree with you","I don't believe that at all","You speak French really well","Go on, keep talking, please"],"microActivity":"\"Paul said he'd quit smoking tomorrow.\" — \"Yeah, right! He says that every month.\"","profNote":"It's all in the ironic tone, like \"yeah, right\": {tu parles !} isn't asking anyone to talk."},"expr-lote1-013":{"meaning":"it's a piece of cake","example":"Changing a light bulb? It's a piece of cake!","secondExample":"For her, the first exam was a piece of cake, but the second one was harder.","literal":"it's cake","options":["It's very expensive","It's very easy","It's a birthday party","It's very sweet"],"microActivity":"Putting together this little piece of furniture with the instructions? Piece of cake, it takes ten minutes.","profNote":"Like \"a piece of cake\", but with {du}, never {un}. The negative is common too: {ce n'est pas du gâteau}."},"expr-lote1-014":{"meaning":"to feel down / to have the blues","example":"On Sunday evenings, I often feel down.","secondExample":"Far from her family, she felt blue all winter.","literal":"to have the cockroach","options":["To be very lucky","To be very energetic","To have an insect at home","To be sad and melancholy"],"microActivity":"Since his best friend moved away, he's been feeling down and doesn't go out anymore.","profNote":"{Cafard} also means cockroach, but here it's a passing sadness. It takes {avoir}: {j'ai le cafard}."},"expr-lote1-015":{"meaning":"to give someone a call","example":"I'm going to give my mom a call.","secondExample":"Yesterday, he gave the doctor a call to make an appointment.","literal":"to pass a blow of wire","options":["To sew a garment","To call someone","To send a letter","To cut a cable"],"microActivity":"Wait two minutes, I need to give my boss a call.","profNote":"Fine anywhere, even at work. Say who with {à}: {passer un coup de fil à Paul}."},"expr-lote1-016":{"meaning":"to stand in line / to wait in line","example":"At the bakery, you have to stand in line on Sundays.","secondExample":"We waited in line for an hour to get into the museum.","literal":"to make the tail","options":["To close the shop early","To wait your turn in line","To make a dish for dinner","To run off really fast"],"microActivity":"There are lots of people at the post office, we're going to have to wait in line.","profNote":"Like British English, French uses {queue} for a line: {je fais la queue}, with {faire}."},"expr-lote1-017":{"meaning":"to be looking forward to it / can't wait","example":"I can't wait to go on vacation!","secondExample":"The kids couldn't wait to open their presents.","options":["To be afraid of something","To be very tired","To be eager for something to happen","To be late"],"microActivity":"My brother arrives from Canada tomorrow, I can't wait to see him again!","profNote":"It takes {de} + verb: {j'ai hâte de partir}. Despite looking like \"haste\", it's not about hurrying."},"expr-lote1-018":{"meaning":"yeah, sure... / tell me another one","example":"— I finished all my homework in ten minutes.\n— Yeah, right!","secondExample":"— I only ate one chocolate.\n— Yeah, right, the box is empty!","literal":"my eye!","options":["Look carefully","I saw it with my own eyes","My eye hurts","I don't believe you at all"],"microActivity":"\"The dog ate my homework, miss.\" — \"Oh, sure! Come up with a better excuse.\"","profNote":"Casual and ironic, for people you know well. The French sometimes pull down an eyelid while saying {mon œil !}"},"expr-lote1-019":{"meaning":"to get on one's high horse / to fly off the handle","example":"As soon as anyone criticizes his project, he gets all worked up.","secondExample":"She flew off the handle when the waiter got the order wrong.","literal":"to climb onto one's big horses","options":["To make a calm decision","To lose one's temper and overreact","To go horseback riding","To become very rich"],"microActivity":"I just made a little remark, no need to get on your high horse like that!","profNote":"Close to \"get on your high horse\", and the possessive changes too: {je monte sur mes grands chevaux}."},"expr-lote1-020":{"meaning":"to hit a wall of tiredness / to feel suddenly drained","example":"After lunch, I always hit a wall around three in the afternoon.","secondExample":"He suddenly felt exhausted at the wheel and pulled over at a rest area.","literal":"to have a blow of the bar","options":["To get hit hard","To find a quick fix","To have a drink at a bar","To feel suddenly exhausted"],"microActivity":"I'm going to take a nap, I'm suddenly wiped out after that big meal.","profNote":"Casual and very common after lunch, like \"I'm crashing\". It takes {avoir} and {un}: {j'ai un coup de barre}."},"expr-lote2-001":{"meaning":"get lost / beat it","example":"\"Get lost, I don't want to see you anymore!\" she yelled at her ex.","secondExample":"The cat got up on the table, so I told him: \"Come on, scram!\"","options":["To thank someone warmly","To ask a neighbor for help","To wish someone a good trip","To tell someone to get lost"],"microActivity":"You're getting on my nerves, get out of my room!","profNote":"It's aggressive, the language of a fight. Elsewhere, the verb {dégager} means \"to clear\"."},"expr-lote2-002":{"meaning":"to leave / to take off","example":"It's late, I'm out of here. See you tomorrow!","secondExample":"When the police showed up, they took off running.","literal":"to break oneself","options":["Fall asleep very quickly","Get hurt in a fall","Leave, go away","Get angry at someone"],"microActivity":"This party sucks, wanna bail?","profNote":"Careful: {se casser} can also mean to break, as in {le verre s'est cassé}. Context tells you."},"expr-lote2-003":{"meaning":"it's a pain / it's a drag","example":"Another hour-long meeting? What a pain in the ass!","secondExample":"Standing in line at the government office was a real pain in the ass.","options":["It's very funny and entertaining","It's very boring or annoying","It's very expensive to buy","It's very easy to do"],"microActivity":"Filling out these forms for three hours is a pain in the ass!","profNote":"It's vulgar but heard a lot. About a person it's insulting: {il est chiant}. Avoid it with strangers."},"expr-lote2-004":{"meaning":"to be scared / to be scared to death","example":"I'm scared to death of flying.","secondExample":"During the horror movie, we were scared stiff all evening.","options":["Be cold","Be ashamed","Be sleepy","Be scared"],"microActivity":"My little brother won't go into the cave: he's scared stiff.","profNote":"Like {avoir peur}, it takes {avoir} and {de}: {j'ai la trouille de prendre l'avion}. Casual."},"expr-lote2-005":{"meaning":"to be dead tired","example":"I'm beat, I worked twelve hours today.","secondExample":"After the marathon, they were completely wiped out.","literal":"to be dead","options":["Be very tired","Be very sick","Be very angry","Be very happy"],"microActivity":"I spent the whole day moving, I'm wiped out.","profNote":"It's casual and agrees with the speaker: a woman says {je suis crevée}. On a tire, {crevé} means flat."},"expr-lote2-006":{"meaning":"to be drunk / to be wasted","example":"He drank six beers, he's completely hammered.","secondExample":"Last night we were so wasted that we took a taxi home.","literal":"to be stuffed","options":["Have had too much to drink","Have eaten too much","Be full of cash","Be in a big hurry"],"microActivity":"After all those bottles of wine, Marc was completely hammered.","profNote":"Party slang, close friends only. The neutral word is {ivre}. A woman says {je suis bourrée}."},"expr-lote2-007":{"meaning":"to be starving","example":"I'm starving, what are we eating tonight?","secondExample":"The kids were starving when they got home from school.","literal":"to have the gullet","options":["Be very thirsty","Feel like sleeping","Be very hungry","Have a stomachache"],"microActivity":"I haven't eaten anything since this morning, I'm starving!","profNote":"Slang, with friends or family. Like {avoir faim}, it takes {avoir}: {j'ai la dalle}."},"expr-lote2-008":{"meaning":"to be a pain in the neck / to bug someone","example":"Quit busting my chops with your questions!","secondExample":"My neighbor drives us nuts with his music every night.","literal":"to break the candies","options":["Annoy someone nonstop","Help someone cook","Give someone gifts","Make everyone laugh"],"microActivity":"You've been repeating the same thing for an hour, you're driving me nuts!","profNote":"Slang, close friends only: a softened form of a cruder phrase. Note the {me}: {tu me casses les bonbons}."},"expr-lote2-009":{"meaning":"stop exaggerating / stop making things up","example":"— I ate ten pizzas yesterday.\n— Get out of here!","secondExample":"You won the lottery twice? Get out of here, I don't believe you!","literal":"stop your chariot","options":["When someone speaks too quietly","When someone exaggerates or lies","When someone drives too fast","When someone leaves too early"],"microActivity":"You speak ten languages? Give me a break!","profNote":"Informal, among friends, when a story sounds too good to be true. With {vous}: {arrêtez votre char}."},"expr-lote2-010":{"meaning":"to pass out","example":"It was so hot in the subway that a lady passed out.","secondExample":"When I see blood, I pass out.","literal":"to fall in the apples","options":["Be in love","Eat too much fruit","Faint","Fall off a bike"],"microActivity":"She hadn't eaten anything and passed out during PE class.","profNote":"Informal and very common. In the past tense {tomber} takes {être}: {elle est tombée dans les pommes}."},"expr-lote2-011":{"meaning":"to give up guessing / to ask for the answer","example":"I can't figure out the answer to your riddle, I give up.","secondExample":"After ten minutes, the students gave up.","literal":"to give one's tongue to the cat","options":["Keep a secret","Talk for too long","Feed your pet","Give up on finding the answer"],"microActivity":"So, did you guess? No? Do you give up?","profNote":"For riddles and guessing games, among friends. {Sa} changes with the person: {je donne ma langue au chat}."},"expr-lote2-012":{"meaning":"to cost a fortune / to cost an arm and a leg","example":"This coat costs an arm and a leg.","secondExample":"Our vacation in Japan cost us an arm and a leg.","literal":"to cost the eyes of the head","options":["Be very beautiful","Be free","Cost a lot","Hurt a lot"],"microActivity":"We can't buy this car, it costs an arm and a leg.","profNote":"English pays an arm and a leg; French pays {les yeux de la tête}. Fine in any conversation."},"expr-lote2-013":{"meaning":"a sleepless night / a night without sleep","example":"The baby cried, so I had a sleepless night.","secondExample":"Before exams, a lot of students pull all-nighters.","literal":"white night","options":["A night without sleep","A very quiet night","A wedding party night","A night with snow"],"microActivity":"I didn't sleep at all: I spent a sleepless night.","profNote":"It usually goes with {passer}: {j'ai passé une nuit blanche}. Party, work or worry, any reason counts."},"expr-lote2-014":{"meaning":"to give up / to throw in the towel","example":"This sudoku is too hard, I'm throwing in the towel.","secondExample":"After three years of problems, they threw in the towel and closed the restaurant.","literal":"to throw the sponge","options":["Give up, quit","Clean the house","Get angry","Start a project"],"microActivity":"He failed his driving test five times, then he threw in the towel.","profNote":"English throws in the towel, French throws the sponge: {jeter l'éponge}. Both come from boxing."},"expr-lote2-015":{"meaning":"to have your head in the clouds","example":"Léa forgot her keys again, she always has her head in the clouds.","secondExample":"During the meeting, I had my head in the clouds.","literal":"to have one's head in the clouds","options":["Have a headache","Be distracted, dreamy","Be afraid of flying","Be very smart"],"microActivity":"You never listen to what I say, you've got your head in the clouds!","profNote":"Same picture as in English, but with {avoir}: {il a la tête dans les nuages}. Fine in any setting."},"expr-lote2-016":{"meaning":"to be generous / to have a heart of gold","example":"My grandmother has a heart of gold: she helps the whole neighborhood.","secondExample":"Our neighbors have always been very generous with us.","literal":"to have the heart on the hand","options":["Be very generous","Be very sick","Be deeply in love","Be very shy"],"microActivity":"Paul often gives his time to people in need: he has a heart of gold.","profNote":"A compliment that works anywhere. Watch the preposition: the heart is {sur la main}, \"on\" the hand."},"expr-lote2-017":{"meaning":"to be tipsy / to be a little drunk","example":"At the end of the wedding, Uncle Bernard was tipsy and singing off-key.","secondExample":"Don't let her drive, she's had a few.","literal":"to have a glass in the nose","options":["Be a bit drunk","Have a cold","Be very curious","Have a broken nose"],"microActivity":"He was laughing too loudly and talking to everyone: he'd clearly had a few.","profNote":"Casual and good-humored, much softer than {être bourré}. Use it to tease, not to insult."},"expr-lote2-018":{"meaning":"to cost an arm and a leg","example":"The tickets for the final cost a bundle.","secondExample":"Fixing my motorcycle cost me a bundle.","literal":"to cost the skin of the butt","options":["Be extremely expensive","Get hurt in a fall","Be very uncomfortable","Cost nothing at all"],"microActivity":"With all these hidden fees, my phone plan is costing me an arm and a leg!","profNote":"Cheekier than {coûter les yeux de la tête}, the everyday version. Keep {la peau des fesses} for friends."},"expr-lote2-019":{"meaning":"to make a mountain out of a molehill","example":"I'm five minutes late, don't make a big deal out of it!","secondExample":"She spilled a little coffee and he made a huge fuss about it.","literal":"to make a whole cheese out of it","options":["Exaggerate a small problem","Tell a funny story","Cook a big meal","Forget an appointment"],"microActivity":"It's just a little scratch on the car, no need to make a mountain out of a molehill.","profNote":"Casual. Don't drop the {en}: {ne va pas en faire tout un fromage !} In French, the fuss becomes a cheese."},"expr-lote2-020":{"meaning":"to give a forced laugh / to laugh it off awkwardly","example":"When his boss made fun of his tie in front of everyone, Thomas gave a forced laugh.","secondExample":"I force a smile every time someone reminds me of my failure on the exam.","literal":"to laugh yellow","options":["Laugh while watching a movie","Laugh without really wanting to","Laugh very loudly for a long time","Laugh to make fun of others"],"microActivity":"She didn't like the joke about her age: she gave a forced laugh.","profNote":"Fine in any setting. {Jaune} never changes, and in the past it's {il a ri jaune}."},"expr-lote3-001":{"meaning":"it's worth it","example":"The museum is a bit pricey, but it's worth it.","secondExample":"— Do you think it was worth getting up at five?\n— Yes, look at that sunrise!","literal":"that's worth the blow","options":["It's worth the effort or money","It costs way too much","It hurts like a blow","It happens all of a sudden"],"microActivity":"This movie is three hours long, but trust me, it's worth it!","profNote":"Very common in everyday talk, with anyone. To say the opposite: {ça ne vaut pas le coup}."},"expr-lote3-002":{"meaning":"bad luck / what a shame","example":"— I missed the bus by two minutes.\n— Ah, tough luck!","secondExample":"It's raining the whole weekend of our vacation, just our luck.","literal":"no bowl","literalNote":"In old slang, \"bol\" meant the backside: \"pas de bol\" is the mild version of \"pas de cul\" (bad luck).","options":["When someone is out of luck","When there's nothing left to eat","When you turn down an invitation","When someone is very hungry"],"microActivity":"The store closed just as we were getting there. Just our luck!","profNote":"Informal, for small mishaps like missing a bus. For truly sad news, {pas de bol} sounds far too light."},"expr-lote3-003":{"meaning":"to be lucky","example":"He found a parking spot right out front, he's so lucky!","secondExample":"We got lucky: the last train waited for us.","literal":"to have a bowl","literalNote":"In old slang, \"bol\" meant the backside: \"avoir du bol\" is the mild version of \"avoir du cul\" (to be lucky).","options":["Be lucky","Be very thirsty","Have lots of money","Have a bad temper"],"microActivity":"She won the lottery on her very first try, she's so lucky!","profNote":"Note the {du}: {il a du bol}. For bad luck it's {pas de bol}. Both are informal, among friends."},"expr-lote3-004":{"meaning":"to be careful / to watch out","example":"Watch out, the floor is wet!","secondExample":"We were careful not to wake the baby when we got home.","options":["Be careful","Make a joke","Make noise","Party"],"microActivity":"Watch out when you cross, cars go fast around here!","profNote":"Casual; in formal settings, {faites attention}. Careful: {faire une gaffe}, with {une}, means to make a blunder."},"expr-lote3-005":{"meaning":"to mess up badly / to fail","example":"I didn't study enough and I bombed the exam.","secondExample":"— Did you take the right road?\n— No, we messed up, we have to turn around.","literal":"to plant oneself","options":["Get it wrong or fail","Settle into a garden","Stop to rest","Get up very early"],"microActivity":"I didn't understand the question and totally blew it: I got a zero!","profNote":"Informal. It's a {se} verb, so the past takes {être}: {je me suis planté}, or {plantée} for a woman."},"expr-lote3-006":{"meaning":"it's terrible / it sucks","example":"This game is too hard and no fun, it sucks.","secondExample":"— The concert is canceled?\n— Yes, that sucks!","literal":"it's null","options":["It's really bad","It's free","It's very easy","It's over"],"microActivity":"This movie is boring and the actors are bad. It sucks!","profNote":"Casual, for things and situations. About a person it's a put-down: {il est nul en maths}, hopeless at math."},"expr-lote3-007":{"meaning":"it's awesome","example":"You got your license? That's awesome!","secondExample":"We're going to the beach tomorrow, it's awesome!","options":["It's great","It's weird","It's hard","It's a shame"],"microActivity":"My parents are giving me a dog for my birthday, that's awesome!","profNote":"For any good news: {c'est génial !} It works for people too: {il est génial}, \"he's amazing\"."},"expr-lote3-008":{"meaning":"oh dear / darn (mild exclamation)","example":"Darn, I forgot my keys!","secondExample":"— The store closes at noon today.\n— Oh, darn!","options":["When you're surprised or disappointed","When you say hello","When you talk about a thin person","When you thank someone"],"microActivity":"Oh shoot, there's no more milk for the coffee!","profNote":"It's the polite stand-in for a swear word, fine in front of kids, like \"darn\". Often just {mince !}"},"expr-lote3-009":{"meaning":"dying of laughter (lol)","example":"His joke was so funny, I was dying laughing.","secondExample":"Check out this cat video, my sister and I were dying laughing!","options":["Laughing really hard","Feeling very tired","Feeling very scared","Feeling very sad"],"microActivity":"When he fell into the pool fully dressed, everyone was in stitches.","profNote":"Informal. It agrees with whoever's laughing: a woman says {j'étais morte de rire}. In texts it's {mdr}."},"expr-lote3-010":{"meaning":"to be on top form","example":"This restaurant is really top-notch, I recommend it.","secondExample":"After a good night's sleep, I'm in top form!","options":["Be excellent","Be at the top of a building","Be late","Be very busy"],"microActivity":"The hotel was clean, the staff was friendly: everything was top-notch.","profNote":"Informal, and it works for people, places or things: {elle est au top}, {ce restaurant est au top}."},"expr-lote3-011":{"meaning":"to lose patience","example":"The bus is an hour late and people are starting to lose patience.","secondExample":"The teacher lost his patience when the students kept chatting.","options":["Be unable to stay calm","Lose an important item","Enjoy waiting","Forget an appointment"],"microActivity":"I've been on hold for thirty minutes, I'm starting to lose patience.","profNote":"No article, just like \"lose patience\" in English: {je perds patience}. Fine in any setting, formal or not."},"expr-lote3-012":{"meaning":"to fall in love","example":"He met Julie on vacation and fell in love.","secondExample":"I think I'm falling in love with this city!","literal":"to fall amorous","options":["To start loving someone","To fall to the ground","To argue with someone","To break up with someone"],"microActivity":"My grandparents met at a dance and fell in love right away.","profNote":"Note the {de}, where English says \"with\": {tomber amoureux de Julie}. In the past it takes {être}: {il est tombé}."},"expr-lote3-013":{"meaning":"shut up (milder than 'ta gueule')","example":"Stop telling everyone my secrets! Shut up!","secondExample":"\"Shut up for a bit, I'm trying to listen to the game!\"","literal":"close it","options":["Be quiet","Close the door","Go to bed","Stop eating"],"microActivity":"You always talk nonsense. Shut up for a second and listen to me!","profNote":"It's rude, even with no swear word: the {la} is the mouth. Still blunt but milder: {tais-toi}."},"expr-lote3-014":{"meaning":"leave me alone","example":"Stop following me everywhere and leave me the hell alone!","secondExample":"\"Leave me the hell alone, I'm working!\" shouted the neighbor.","options":["Leave me alone","Come help me","Make peace with me","Speak louder to me"],"microActivity":"That's the tenth time you've asked me the same question, leave me the hell alone!","profNote":"It sounds angry and rude, so only with people you're very close to. Politer: {laisse-moi tranquille}."},"expr-lote3-015":{"meaning":"are you kidding me?","example":"You're asking me for another hundred euros? Are you kidding me?","secondExample":"— The plumber said he'd come next Tuesday.\n— Is he messing with us or what?","options":["Are you making fun of me?","Are you scared of me?","Are you thinking of me?","Are you coming with me?"],"microActivity":"You show up two hours late and tell me \"I'm early\"? Are you kidding me?","profNote":"Slang for reacting to something outrageous, close friends only. Milder: {tu te moques de moi ?}"},"expr-lote3-016":{"meaning":"damn / hell (strong exclamation)","example":"Dammit, another traffic jam on the highway!","secondExample":"\"What the hell is this mess?\" asked the teacher when he saw the classroom.","literal":"brothel","options":["When someone is annoyed or facing a mess","When someone is grateful for a gift or a favor","When someone is calm or sees something lovely","When someone greets a friend or a neighbor"],"microActivity":"What the hell is going on? Everyone's yelling in the hallway!","profNote":"It can shock, so never with strangers. It also means a big mess: {c'est le bordel ici}."},"expr-lote3-017":{"meaning":"strong exclamation (surprise, anger)","example":"Shit, I missed the train again!","secondExample":"\"Holy shit, it's beautiful!\" said Marc, looking at the sea.","literal":"whore","options":["To express a strong emotion","To ask politely","To say goodbye","To thank someone"],"microActivity":"This fucking alarm clock didn't go off this morning!","profNote":"It covers anger, shock, even awe, but it's crude: recognize {putain} and never use it with strangers."},"expr-lote3-018":{"meaning":"you idiot (insult)","example":"\"You dumbass, watch where you're walking!\"","secondExample":"He shouted \"you dumbass!\" at the driver who hadn't stopped.","literal":"kind of idiot","options":["It's an insult: \"idiot\"","It's a compliment","It's a way of saying hello","It's a word for apologizing"],"microActivity":"You dumbass, you broke my bike!","profNote":"A real insult that can start a fight: best to just recognize it. For a woman it becomes {espèce de conne}."},"expr-lote3-019":{"meaning":"jerk / asshole (insult)","example":"That asshole cut ahead of me in line without saying anything.","secondExample":"\"What an asshole, he didn't even say thank you!\"","options":["It's an insult for a man","It's a nickname for a friend","It's the name of a job","It's a compliment for someone"],"microActivity":"This guy isn't just a bit dumb, he's a real asshole: he hurts people on purpose.","profNote":"A strong insult, best kept for recognizing. It's masculine; for a woman French uses {connasse}."},"expr-lote3-020":{"meaning":"to be completely off the mark","example":"His answer has nothing to do with the question, he's completely off base.","secondExample":"I was completely off: I thought the meeting was tomorrow.","literal":"to be next to the plate","options":["To be completely wrong","To be sitting next to someone","To be late for dinner","To be very attentive"],"microActivity":"You're talking about vacation while we're looking for a solution to the problem? You're totally off the mark!","profNote":"Casual, for someone way off base. Often with {complètement} before it: {il est complètement à côté}."},"expr-lote4-001":{"meaning":"to pretend","example":"He pretends to be asleep when his mother comes in.","secondExample":"I pretended to like the cake to be polite.","literal":"to make appearance","options":["To act as if it were true","To do something very fast","To always tell the truth","To do the same as a friend"],"microActivity":"The little boy isn't sleeping, he's pretending to sleep.","profNote":"Where English says \"pretend that\", French prefers {de} + verb: {il fait semblant de dormir}."},"expr-lote4-002":{"meaning":"to do on purpose","example":"\"Sorry, it wasn't on purpose!\" said Léa after she broke the glass.","secondExample":"My brother sings loudly on purpose to annoy me.","literal":"to do expressly","options":["To do something on purpose","To do something too late","To do something with a friend","To do something very well"],"microActivity":"Sorry for pushing you, I didn't do it on purpose!","profNote":"Very common in the negative, to apologize: {je n'ai pas fait exprès}. The final {s} is silent."},"expr-lote4-003":{"meaning":"to turn the page, to move on","example":"After his divorce, Paul decided to turn the page and move away.","secondExample":"We argued a long time ago, now we need to move on.","options":["To leave the past behind","To read a book very quickly","To bring up an old argument","To change your mind often"],"microActivity":"That job made me unhappy for years, but I've finally turned the page.","profNote":"Same image as in English, and fine anywhere, even at work: {il faut tourner la page}."},"expr-lote4-004":{"meaning":"to hold a grudge against someone","example":"She's still upset with her friend for forgetting her birthday.","secondExample":"— Are you mad at me?\n— No, it's forgotten.","options":["To hold a grudge against someone","To want to see someone","To ask someone a favor","To be jealous of someone"],"microActivity":"He lied to me, so I'm still a bit mad at him.","profNote":"Nothing to do with wanting. Don't drop the {en}: {je t'en veux} means \"I hold it against you\"."},"expr-lote4-005":{"meaning":"it's over, it's lost","example":"We missed the last train, that's it for tonight.","secondExample":"The project fell through, it's all ruined.","options":["When there's no hope left","When everything is going really well","When you want to thank someone","When you start a project"],"microActivity":"Two minutes left and we're losing three to nothing: we're done for.","profNote":"Informal and a bit crude: skip it at work. A milder version is {c'est fichu}."},"expr-lote4-006":{"meaning":"to be broke","example":"I can't go out this weekend, I'm totally broke.","secondExample":"When we were students, we were always broke at the end of the month.","literal":"to be mown","options":["To have no money","To be very tired","To have too much work","To be sick"],"microActivity":"Can you pay for the coffee? I don't have a single euro left, I'm broke.","profNote":"Casual and very common. It agrees with the speaker: a woman says {je suis fauchée}."},"expr-lote4-007":{"meaning":"to be upset, angry or disappointed","example":"I'm bummed, my favorite concert got canceled.","secondExample":"She was crushed when she failed her driving test by one point.","literal":"to have the balls","options":["To be upset","To be very happy","To be cold","To be hungry"],"microActivity":"We lost the game in the last second, I'm so bummed!","profNote":"Not \"have the balls\" (be brave): {j'ai les boules} means you're gutted. Very casual, friends only."},"expr-lote4-008":{"meaning":"to be full of energy / to be in high spirits","example":"This morning I'm full of energy: I'm going for a run before work.","secondExample":"After her vacation, my grandmother was really full of pep.","literal":"to have the peach","options":["To be full of energy","To feel like eating fruit","To be in a bad mood","To be sleepy"],"microActivity":"I slept well, today I'm raring to go!","profNote":"Casual, and always with {avoir} and {la}: {j'ai la pêche}. Nobody's talking fruit here, it's all energy."},"expr-lote4-009":{"meaning":"to struggle / to have a hard time","example":"I struggled to find an apartment in Paris.","secondExample":"The new students are struggling a bit with math.","literal":"to row in a galley","options":["To struggle a lot with something","To go on a long boat trip","To do something very easily","To refuse to do any work"],"microActivity":"Without GPS, we struggled for an hour to find the hotel.","profNote":"A casual verb, conjugated like {parler}: {j'ai galéré}. For a hard task, say {c'est la galère}."},"expr-lote4-010":{"meaning":"to have money / to have cash","example":"His parents have loads of cash, they go on vacation three times a year.","secondExample":"If I had some cash, I'd buy a house by the sea.","options":["To have money","To be cold","To be lucky","To have friends"],"microActivity":"He drives a luxury car, he must be loaded.","profNote":"{Le fric} is slang for {l'argent}: fine with friends, but at a job interview or the bank, stick to {argent}."},"expr-lote4-011":{"meaning":"you're pissing me off / you're a pain in the ass","example":"\"Stop asking me the same question, you're pissing me off!\"","secondExample":"His lame jokes really piss me off.","literal":"you cover me in shit","options":["When someone really annoys you","When you want to congratulate someone","When you say goodbye politely","When you ask for help"],"microActivity":"That's the tenth time you've knocked on my door, you're pissing me off!","profNote":"Vulgar and hurtful: understand it, but don't say it. Without the swear word, French says {tu m'embêtes}."},"expr-lote4-012":{"meaning":"get lost / go to hell","example":"He asked me to do his job for him; I told him to get lost.","secondExample":"\"Get lost with your advice!\" shouted the neighbor.","literal":"go get yourself seen","options":["To reject someone angrily","To invite someone to a party","To suggest a guided tour","To thank a friend"],"microActivity":"You want me to lend you money again? No, go to hell!","profNote":"{Va te faire voir} is rude and ends the talk in anger. It softens a swear, but avoid it, even with friends."},"expr-lote4-013":{"meaning":"to sulk / to wear a sour face","example":"Ever since we refused to go to the restaurant, Julien has been sulking.","secondExample":"She sulked all evening because they had forgotten to invite her.","literal":"to pull the muzzle","options":["To look angry and sulk","To laugh very loudly","To talk nonstop","To make faces to amuse people"],"microActivity":"He didn't get the present he wanted, so he's been sulking since this morning.","profNote":"{La gueule} is an animal's mouth, so it sounds crude. Fine with friends; with your boss, say {faire la tête}."},"expr-lote4-014":{"meaning":"to make fun of someone / to mess with someone","example":"Did you see the price of this sandwich? They must think we're idiots!","secondExample":"Quit messing with me, I know you're lying.","options":["To make fun of someone","To admire someone","To secretly help someone","To politely ignore someone"],"microActivity":"Three hours late and no apology? They're screwing with us!","profNote":"Very crude because of {foutre}: friends only. The possessive changes: {ils se foutent de notre gueule}."},"expr-lote4-015":{"meaning":"to be on edge / to be all keyed up","example":"With exams coming up, everyone is on edge.","secondExample":"Don't talk to him about the bill now, he's already on edge.","literal":"to be on the nerves","options":["To be tense and irritable","To be perfectly calm","To be playing sports","To be deeply in love"],"microActivity":"She hasn't slept in two days because of the move, she's on edge.","profNote":"It takes {être} and {les}: {je suis sur les nerfs}. Casual, but very natural in everyday talk."},"expr-lote4-016":{"meaning":"it's raining cats and dogs","example":"Take an umbrella, it's pouring outside!","secondExample":"Yesterday it was pouring rain and the game was canceled.","literal":"it's raining ropes","options":["It's raining very hard","It's very hot","It's very windy","It's starting to snow"],"microActivity":"I'm soaked: when I came out of the subway, it was raining cats and dogs!","profNote":"Like \"it's pouring\", it only works with {il}: {il pleut des cordes}, never {ça pleut}."},"expr-lote4-017":{"meaning":"to go all out / to pull out all the stops","example":"For his daughter's wedding, he went all out: orchestra, fireworks, everything.","secondExample":"If we want to win the final, we'll have to give it everything we've got.","literal":"to put the package","options":["To give it everything","To send a package by mail","To do the bare minimum","To give up on a project"],"microActivity":"The interview is tomorrow: tonight I'm going over everything, I'm going all out!","profNote":"Casual and positive: always {le paquet}, singular. In the past: {il a mis le paquet}."},"expr-lote4-018":{"meaning":"at full speed / flat out","example":"A motorcycle zoomed past the school at full speed.","secondExample":"We were late, so we raced across the city at full speed.","literal":"to the floor, the box (slang: the car)","options":["At full speed","Very slowly","In silence","Very carefully"],"microActivity":"The delivery guy floored it and nearly ran over a pedestrian.","profNote":"Casual, mostly about cars and bikes: {la caisse} is slang for a car. With friends, plain {à fond} works too."},"expr-lote4-019":{"meaning":"it's nothing special","example":"The movie is watchable, but it's nothing special.","secondExample":"His new album was nothing special, the reviews were lukewarm.","literal":"it doesn't break bricks","options":["It's nothing special","It's really great","It's very dangerous","It's breaking"],"microActivity":"This restaurant is okay, but honestly, it's nothing to write home about.","profNote":"Casual and always negative. In speech, the {ne} often drops: {ça casse pas des briques}."},"expr-lote4-020":{"meaning":"to be crazy / to be nuts","example":"You want to swim in the sea in January? You're nuts!","secondExample":"My neighbor is a bit crazy: he talks to his plants all day long.","literal":"to be lashed","options":["To be crazy","To be very smart","To be tired","To be shy"],"microActivity":"Cross the highway on foot? You'd have to be nuts!","profNote":"Casual, for friends. It agrees with the person: {il est cinglé}, {elle est cinglée}."},"lt-a1m6-005":{"referenceTranslations":["I like to listen to music.","I like listening to music.","I love listening to music."],"explanation":"\"Aimer\" + infinitive says what you like doing; \"de la musique\" is the partitive (music in general)."},"lt-a1m6-006":{"referenceTranslations":["Last night I ate an apple.","Last night, I ate an apple.","Yesterday evening I ate an apple."],"explanation":"\"Hier soir\" (\"last night\") calls for the passé composé: \"j'ai mangé\" (avoir + the past participle of \"manger\")."},"accent-a1m6-006":{"explanation":"Both \"e\"s have an acute accent."},"accent-a1m6-007":{"explanation":"The last two \"e\"s have an acute accent."},"cloze-a1m6-001":{"translation":"Yesterday, we ate at the restaurant.","explanation":"\"Manger\" forms the passé composé with avoir: nous avons mangé. Most verbs use avoir."},"cloze-a1m6-002":{"translation":"Yesterday, she went to the movies.","explanation":"\"Aller\" is a verb of movement and uses être: elle est allée. With être, the past participle agrees with the subject (allée, feminine)."},"cloze-a1m6-003":{"translation":"Last weekend, I played sports.","explanation":"The past participle of \"faire\" is irregular: fait. With avoir, it doesn't agree with the subject, so no -e."},"cloze-a1m6-004":{"translation":"This morning, Sophie went to the market.","explanation":"With être, the past participle agrees with the subject: Sophie is feminine, so allée (with -e). \"Aller\" is the infinitive, not the past participle."},"cloze-a1m6-005":{"translation":"He took the train the day before yesterday.","explanation":"\"Prendre\" uses avoir (il a pris), even though it's about traveling: only a small group of movement verbs, like aller, use être. The past participle is irregular: pris."},"cloze-a1m6-006":{"translation":"Last weekend, we went to the movies.","explanation":"\"Aller\" uses être (nous sommes), and the past participle agrees with the plural subject: allés (with -s)."},"accent-a1-001":{"explanation":"\"e\" has an acute accent: école."},"accent-a2-001":{"explanation":"\"a\" has a grave accent and \"o\" has a circumflex accent: à bientôt."},"accent-b2-001":{"explanation":"The first two \"e\"s have an acute accent: préférer (pré-fé-rer). The last \"e\" has no accent."},"expr-a1-001":{"meaning":"To feel hunger; to want to eat.","example":"I'm very hungry. I want to eat.","secondExample":"We're hungry after playing sports.","literal":"to have hunger","options":["To be tired","To be thirsty","To want to eat","To be happy"],"microActivity":"It's noon. I'm hungry!","profNote":"In French you have hunger, with {avoir}: {j'ai faim}, never {je suis faim}."},"expr-a1-002":{"meaning":"The feeling of wanting to drink.","example":"It's hot, I'm thirsty.","secondExample":"After playing sports, we're thirsty.","literal":"to have thirst","options":["To be hungry","To be thirsty","To be cold","To be hot"],"microActivity":"I ran 5 kilometers, now I'm thirsty.","profNote":"Just like hunger: you have thirst. {J'ai soif} works anywhere, with friends or strangers."},"expr-a1-003":{"meaning":"When you hold the right opinion or give the correct answer.","example":"Paul says: 'I think I'm right.'","secondExample":"She's right, the store is closed.","literal":"to have reason","options":["To be tired","To be hungry","To be right","To be thirsty"],"microActivity":"You say the movie is good. I think you're right.","profNote":"French says you \"have reason\": {avoir raison}. The opposite also takes {avoir}: {avoir tort}, to be wrong."},"expr-a2-001":{"meaning":"Help; a helping hand.","example":"I need a hand carrying these heavy boxes.","secondExample":"My neighbors gave me a hand with the move.","literal":"blow of the hand","literalNote":"It was a quick surprise attack (military, 18th century); it later came to mean quick help (19th century).","options":["A difficult problem","A little help","Great fatigue","A sudden idea"],"microActivity":"Can you give me a hand to finish this job?","profNote":"Everyday French, fine even with coworkers. The helper {donne un coup de main}: {tu me donnes un coup de main ?}"},"expr-a2-002":{"meaning":"To feel nervous or scared before doing something important; stage fright.","example":"Before going on stage, the actor had stage fright.","secondExample":"When she has to speak in public, she always gets nervous.","options":["To be very happy.","To be scared or nervous.","To be tired.","To be hungry."],"microActivity":"Tomorrow I have to present my project in front of the whole class. I think I'm going to get stage fright.","profNote":"The nerves right before an exam, a show, an interview, not fear in general. It's {j'ai le trac}."},"expr-a2-003":{"meaning":"To sleep in; to wake up late.","example":"On Sundays, I like to sleep in and not get up early.","secondExample":"After the party, we slept in on Saturday.","literal":"to do the fat morning","options":["To wake up very early in the morning.","To go to bed very early at night.","To get up late in the morning.","To take a nap in the afternoon."],"microActivity":"When I'm on vacation, I love sleeping in.","profNote":"It takes {faire}: {je fais la grasse matinée}. The classic Sunday plan, fine to say to anyone."},"expr-b2-001":{"meaning":"To set the record straight; to make everything perfectly clear.","example":"Although the project had been approved in principle, there was still a need to dot the i's and cross the t's on the budget details.","secondExample":"After the meeting, the manager asked his team to dot the i's and cross the t's before submitting the final report.","literal":"to put the dots on the i's","options":["To be tired of everything","To clarify every detail","To argue over little things","To make a rushed decision"],"microActivity":"Before signing the contract, we absolutely have to dot the i's and cross the t's to avoid any future misunderstanding.","profNote":"Like \"dot the i's\", but often firmer, close to \"set the record straight\": {mettre les points sur les i}."},"expr-b2-002":{"meaning":"To be lazy; to have an aversion to work.","example":"Although his project is ambitious, he seems to be allergic to work, since he constantly puts off deadlines.","secondExample":"My roommate is really lazy: he never does the dishes.","literal":"to have a hair in the hand","options":["To be very hardworking and efficient.","To have great manual dexterity.","To be lazy and avoid work.","To have a slight pain in one's finger."],"microActivity":"It's amazing how lazy he is, even though he's so talented.","profNote":"Casual and a bit teasing. Note the {un}: it's always {un poil}, a single hair, never {des poils}."},"expr-b2-003":{"meaning":"To act with great force and energy, without holding back.","example":"Although the subject is sensitive, the speaker did not hold back in denouncing social injustices.","secondExample":"Despite the warnings, she defended her project without holding back in the face of the harsh criticism.","literal":"not to go with a dead hand","options":["To speak gently and diplomatically.","To act with force and determination, without restraint.","To express one's opinion hesitantly.","To criticize in a subtle, indirect way."],"microActivity":"Faced with this blatant injustice, he decided not to pull any punches to make his voice heard.","profNote":"Always negative, and watch the {y}: {tu n'y vas pas de main morte !}, {il n'y est pas allé de main morte}."},"lt-a1-001":{"referenceTranslations":["I'm eating an apple.","I am eating an apple.","I eat an apple."]},"lt-a2-001":{"referenceTranslations":["I bought a new book last night and I've already started it.","I bought a new book last night and I already started it.","Last night I bought a new book and I've already started reading it.","I bought a new book yesterday evening and have already started it."]},"lt-b1-001":{"referenceTranslations":["Last night I watched an interesting movie on TV, but I fell asleep before the end.","Last night, I watched an interesting film on television, but I fell asleep before the end.","Yesterday evening I watched an interesting movie on TV, but I fell asleep before it ended."]},"lt-b2-001":{"referenceTranslations":["Even though the project is ambitious, we are convinced that we will manage to see it through thanks to everyone's collaboration.","Even if the project is ambitious, we're confident we'll succeed in carrying it out thanks to everyone working together.","Although the project is ambitious, we're sure we'll pull it off thanks to everyone's cooperation."],"explanation":"\"Mener à bien\" means to carry something through successfully, to see it through to the end. Here \"le\" (it) stands for the project: \"le mener à bien\" = \"to see it through\"."}};
